import streamlit as st
CSS="""<style>
:root{--bg:#15181d;--panel:#20242b;--panel2:#262b33;--line:#363d47;--text:#f4f6f8;--muted:#98a2ad;--blue:#63a4ff;--green:#53d38a;--red:#ff7272}
.stApp{background:var(--bg);color:var(--text)}[data-testid=stSidebar]{background:#191d23;border-right:1px solid var(--line)}[data-testid=stSidebar] *{color:#e9edf2!important}.block-container{max-width:1450px;padding-top:1.4rem;padding-bottom:3rem}h1,h2,h3{letter-spacing:-.025em}.desk-kicker{color:var(--blue);font-size:.72rem;letter-spacing:.18em;font-weight:800;text-transform:uppercase}.desk-title{font-size:2.15rem;font-weight:760;margin:.18rem 0 .25rem}.desk-subtitle{color:var(--muted);margin-bottom:1.3rem}.section-title{color:#dce3eb;font-size:.77rem;letter-spacing:.14em;font-weight:800;text-transform:uppercase;margin:1.5rem 0 .65rem}.brief-card,.metric-card,.asset-card,.attention-card{background:linear-gradient(180deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:14px;padding:1rem 1.05rem;box-shadow:0 7px 20px rgba(0,0,0,.14);height:100%}.metric-label{color:var(--muted);font-size:.75rem;text-transform:uppercase;letter-spacing:.09em}.metric-value{color:var(--text);font-size:1.72rem;font-weight:760;margin:.22rem 0 .12rem}.metric-note{color:var(--muted);font-size:.82rem}.asset-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem}.asset-symbol{font-size:1.18rem;font-weight:800}.asset-name{color:var(--muted);font-size:.76rem}.score{font-size:1.15rem;font-weight:800;color:var(--blue)}.data-row{display:flex;justify-content:space-between;gap:1rem;border-top:1px solid rgba(255,255,255,.065);padding:.42rem 0;font-size:.85rem}.data-row span:first-child{color:var(--muted)}.positive{color:var(--green);font-weight:700}.negative{color:var(--red);font-weight:700}.neutral{color:#dce3eb;font-weight:700}.badge{display:inline-block;border:1px solid var(--line);background:#1a1e24;border-radius:999px;padding:.17rem .48rem;font-size:.69rem;color:#dce3eb}.summary-box{background:#1b1f25;border-left:3px solid var(--blue);border-radius:9px;padding:.85rem 1rem;color:#dce3eb;line-height:1.55}.small-muted{color:var(--muted);font-size:.78rem}.progress-track{background:#171a1f;border-radius:999px;height:7px;overflow:hidden;margin:.45rem 0}.progress-fill{background:linear-gradient(90deg,#63a4ff,#8fc1ff);height:100%;border-radius:999px}div[data-testid=stDataFrame]{border:1px solid var(--line);border-radius:12px;overflow:hidden}
</style>"""
def apply_theme():st.markdown(CSS,unsafe_allow_html=True)
